const Profile::MESG* Profile::GetMesg(const FIT_UINT16 num)
{
    // Build a static hash index once.
    struct Index
    {
        static const int SIZE = 512; // power of two > 2*MESGS
        const MESG* table[SIZE];
        Index()
        {
            for (int i = 0; i < SIZE; i++) table[i] = NULL;
            for (int i = 0; i < MESGS; i++)
            {
                unsigned h = (unsigned)mesgs[i].num * 2654435761u;
                h = (h >> 16) & (SIZE - 1);
                while (table[h] != NULL)
                    h = (h + 1) & (SIZE - 1);
                table[h] = &mesgs[i];
            }
        }
    };
    static const Index idx;
    unsigned h = (unsigned)num * 2654435761u;
    h = (h >> 16) & (Index::SIZE - 1);
    while (idx.table[h] != NULL)
    {
        if (idx.table[h]->num == num)
            return idx.table[h];
        h = (h + 1) & (Index::SIZE - 1);
    }
    return NULL;
}
```

